
import type { MoneyValue } from './MoneyValue.js';
import type { PaymentSourceSummary } from './PaymentSourceSummary.js';

export type PaymentRefund = { "amount_money": MoneyValue; /** Flint-normalized refund failure reason. Unknown provider values are returned as refund_failed. */ "failure_reason"?: "expired_or_canceled_card" | "lost_or_stolen_card" | "insufficient_funds" | "insufficient_available_balance" | "declined" | "merchant_request" | "payment_disputed" | "payment_refund_failed" | "payment_refund_not_attempted" | "refund_failed" | (string & {}); "payment_intent"?: (({ "amount_money": MoneyValue; "capture_method"?: "automatic" | "manual" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "order_id"?: string; "payment_intent_id": string; "payment_source"?: PaymentSourceSummary; "refund_status"?: "none" | "partially_refunded" | "refunded" | (string & {}); "status": "requires_payment_method" | "requires_confirmation" | "requires_action" | "processing" | "requires_capture" | "canceled" | "succeeded" | "expired" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "payment_intent_id"?: string; "refunded_tip_money": MoneyValue; "status": "pending" | "in_transit" | "succeeded" | "failed" | "requires_action" | "canceled" | "partially_succeeded" | (string & {}); };
